module Moderate
  class GamesController < BaseController
    layout "screen"

    before_action :set_quiz, only: [ :create ]
    before_action :set_game, only: [ :show, :start, :finish_question, :next_question, :end_game, :top_winners, :draw_winners, :reset_winners, :state ]

    def create
      game = Game.create_from_quiz!(@quiz)
      redirect_to moderate_game_path(game), status: :see_other
    end

    def show
      @join_url = join_url_for(@game)
    end

    def start
      @game.start!
      broadcast_and_respond
    end

    def finish_question
      @game.finish_question!
      broadcast_and_respond
    end

    def next_question
      @game.next_question!
      broadcast_and_respond
    end

    def end_game
      @game.end_game!
      broadcast_and_respond
    end

    def top_winners
      @game.pick_top_winners!
      broadcast_and_respond
    end

    def draw_winners
      @game.draw_winners!
      broadcast_and_respond
    end

    def reset_winners
      @game.reset_winners!
      broadcast_and_respond
    end

    def state
      if params[:v].present? && params[:v] == @game.moderator_state_key
        head :no_content
        return
      end

      @join_url = join_url_for(@game)
      render :state
    end

    private

    def set_quiz
      @quiz = Quiz.find(params[:quiz_id])
    end

    def set_game
      @game = Game.find(params[:id])
    end

    def join_url_for(game)
      play_game_url(game.code)
    end

    def broadcast_and_respond
      @game.reload
      @join_url = join_url_for(@game)

      GameBroadcaster.broadcast_moderator_stage(@game, join_url: @join_url)
      GameBroadcaster.broadcast_players_stage(@game)

      respond_to do |format|
        format.turbo_stream
        format.html { redirect_to moderate_game_path(@game), status: :see_other }
      end
    end
  end
end
